// Internal API to convert input data into output font data
// Used by both CLI and Web wrappers.
'use strict';

const collect_font_data = require('./collect_font_data');

let writers = {
  dump: require('./writers/dump'),
  bin: require('./writers/bin'),
  lvgl: require('./writers/lvgl')
};


//
// Input:
// - args like from CLI (optionally extended with binary content of files)
//
// Output:
// - { name1: bin_data1, name2: bin_data2, ... }
//
// returns hash with files to write
//
module.exports = async function convert(args) {
  // Generate opts_string for Web environment
  if (!args.opts_string) {
    let opts = [];
    
    // Add bpp
    opts.push(`--bpp ${args.bpp}`);
    
    // Add size
    opts.push(`--size ${args.size}`);
    
    // Add compress option if false
    if (args.compress === false) {
      opts.push('--no-compress');
    }
    
    // Add font file name
    opts.push(`--font ${args.font[0].source_path}`);
    
    // Add symbols if specified
    if (args.font[0].ranges) {
      for (let range of args.font[0].ranges) {
        if (range.symbols) {
          opts.push(`--symbols "${range.symbols}"`);
        }
      }
    }
    
    // Add other options as needed
    if (args.stride) opts.push(`--stride ${args.stride}`);
    if (args.align) opts.push(`--align ${args.align}`);
    
    args.opts_string = opts.join(' ');
  }
  
  let font_data = await collect_font_data(args);
  let files = writers[args.format](args, font_data);

  return files;
};

module.exports.formats = Object.keys(writers);
